SELECT "nct", "author", "year", "pubmed_id", "trial_name", "cancer_type", "treatment_regimen", "ici_name", "ici_class", "therapy_type", "clinical_setting", "trial_phase", "control_regimen", "control_type" FROM public."clinical_trials" WHERE "trial_phase" = 'Phase 3' AND "cancer_type" ILIKE '%Small Cell Lung%' AND "therapy_type" = 'Combination therapy' AND "combination_type" = 'ICI + Chemo' AND "control_type" = 'Chemo'